update country_flag_history set label_fr = 'Raj britannique (Étoile de l''Inde)', label_en = 'British Raj (Star of India)', notes_fr = 'Pavillon de l''Empire des Indes britanniques : l''Union Jack frappé de l''étoile de l''ordre de l''Étoile de l''Inde. Il n''a jamais été un drapeau national officiel, rôle tenu par l''Union Jack.', notes_en = 'Flag of the British Indian Empire: the Union Jack bearing the star of the Order of the Star of India. It was never an official national flag; that role belonged to the Union Jack.' where id = 2408 and iso_code = 'in';
update country_flag_history set image_url = '/flags/history/in-0000.svg' where id = 2164 and iso_code = 'in';
